36	    private static final int AUTUMN_TEMP_CHANGE_IDX = 7;
37	    private static final int PLANT_CONCENTRATION_IDX = 8;
38	    private static final int EXPECTED_FIELD_COUNT    = 9;
39	
40	    /**
41	     * Build a HabitatCSVReader and initialize its fields.
42	     */
43	    public HabitatCSVReader() {
44	        errorThrower = new ErrorThrower();
45	        winterTemperatures = new int[2];
46	        autumnTemperatures = new int[2];
47	        springTemperatures = new int[2];
48	        summerTemperatures = new int[2];
49	        plantConcentration = 0;
50	    }
51	
52	    /**
53	     * Populate the fields with the data extracted from the .csv file. Fields are used to store data of the right type to be easily fetched
54	     * by the Initializer when trying to get information about a specific habitat.
55	     * Habitat name from the data is removed to facilitate reading, the first 12 elements are in groups of 2 relating to each season
56	     * (average temperature, and maximum change to temperature ), the 13th element is the plant concentration in that habitat.
57	     *
58	     * @param extractedData (String[]) the data from the CSV file relative to a specific habitat.
59	     */
60	    protected void populateFields(String[] extractedData)
61	    {
62	        extractedData = removeHabitatName(extractedData);
63	        if (extractedData.length != EXPECTED_FIELD_COUNT) {
64	            errorThrower.throwMessage("Habitat issue, please restart.");
65	        }
66	
67	        winterTemperatures[0] = Integer.parseInt(extractedData[WINTER_AVG_TEMP_IDX]);
68	        winterTemperatures[1] = Integer.parseInt(extractedData[WINTER_TEMP_CHANGE_IDX]);
69	        springTemperatures[0] = Integer.parseInt(extractedData[SPRING_AVG_TEMP_IDX]);
70	        springTemperatures[1] = Integer.parseInt(extractedData[SPRING_TEMP_CHANGE_IDX]);
71	        summerTemperatures[0] = Integer.parseInt(extractedData[SUMMER_AVG_TEMP_IDX]);
72	        summerTemperatures[1] = Integer.parseInt(extractedData[SUMMER_TEMP_CHANGE_IDX]);
73	        autumnTemperatures[0] = Integer.parseInt(extractedData[AUTUMN_AVG_TEMP_IDX]);
74	        autumnTemperatures[1] = Integer.parseInt(extractedData[AUTUMN_TEMP_CHANGE_IDX]);
75	        plantConcentration    = Double.parseDouble(extractedData[PLANT_CONCENTRATION_IDX]);
76	    }
77	
78	    /**
79	     * Set all parameters back to initial values before reading data for another habitat.
80	     */
81	    protected void resetParameters()
82	    {
83	        winterTemperatures = new int[2];
84	        springTemperatures = new int[2];
85	        summerTemperatures = new int[2];
86	        autumnTemperatures = new int[2];
87	        plantConcentration = 0;
88	
89	    }
90	
91	    /**
92	     * Returns the list of extracted data without the habitat's name (as this informaiton is known by the Initializer and will therefore
93	     * not be asked). The name is the first element of the attributes list.
94	     *
95	     * @param attributes (String[]) the data from the CSV file relative to a specific habitat.
96	     * @return (String[]) The data without the habitat's name.
97	     */
98	    private String[] removeHabitatName(String[] attributes)
99	    {
100	        String[] attributesWithoutHabitatName = Arrays.copyOfRange(attributes,1,attributes.length);
101	        return attributesWithoutHabitatName;
102	    }
103	
104	    /**
105	     * @return (String) The name of the file containing habitat data.
106	     */
107	    protected String getFileName() {
108	        return FILE_NAME;
109	    }
110	
111	    /**
112	     * @return (int[]) Minimum, average, and maximum temperatures for the winter.
113	     */
114	    public int[] getWinterTemperatures()
115	    {
116	        return winterTemperatures;
117	    }
118	
119	    /**
120	     * @return (int[]) Minimum, average, and maximum temperatures for the autumn.
121	     */
122	    public int[] getAutumnTemperatures() {
123	        return autumnTemperatures;
124	    }
125	
126	    /**
127	     * @return (int[]) Minimum, average, and maximum temperatures for the spring.
128	     */
129	    public int[] getSpringTemperatures() {
130	        return springTemperatures;
131	    }
132	
133	    /**
134	     * @return (int[]) Minimum, average, and maximum temperatures for the summer.
135	     */
136	    public int[] getSummerTemperatures() {
137	        return summerTemperatures;
138	    }
139	
140	    /**
141	     * @return (double) The concentration of plants in the habitat.
142	     */
143	    public double getPlantConcentration() {
144	        return plantConcentration;
145	    }
146	}

